/**
 * Pipedrive Node - Version 2
 * Discriminator: resource=person, operation=get
 */


interface Credentials {
  pipedriveApi: CredentialReference;
  pipedriveOAuth2Api: CredentialReference;
}

/** Get an activity */
export type PipedriveV2PersonGetParams = {
  resource: 'person';
  operation: 'get';
  authentication?: 'apiToken' | 'oAuth2' | Expression<string>;
/**
 * ID of the person to get
 * @default 0
 */
    personId?: number | Expression<number>;
/**
 * Whether to show raw Pipedrive field keys and option IDs instead of human-readable names in output
 * @default false
 */
    rawCustomFieldOutput?: boolean | Expression<boolean>;
};

export type PipedriveV2PersonGetOutput = {
  add_time?: string;
  custom_fields?: Record<string, unknown>;
  emails?: Array<{
    label?: string;
    primary?: boolean;
    value?: string;
  }>;
  first_name?: string;
  id?: number;
  is_deleted?: boolean;
  label_ids?: Array<unknown>;
  last_name?: string;
  name?: string;
  org_id?: number;
  owner_id?: number;
  phones?: Array<{
    label?: string;
    primary?: boolean;
    value?: string;
  }>;
  picture_id?: unknown;
  update_time?: string;
  visible_to?: number;
};

export type PipedriveV2PersonGetNode = {
  type: 'n8n-nodes-base.pipedrive';
  version: 2;
  config: NodeConfig<PipedriveV2PersonGetParams> & { credentials?: Credentials };
  output?: Items<PipedriveV2PersonGetOutput>;
};